 NgayDay = ngayDayStr,
 MaLopHoc = selectedLop!!.MaLopHoc,
 MaCaHoc = selectedCaHoc!!.MaCaHoc!!,
 MaMonHoc = selectedMonHoc!!.MaMonHoc,
 Thu = selectedThu!!,
 MaTuan = selectedTuanTu!!.MaTuan,
