 NoiDung = "Lịch dạy môn ${selectedMonHoc!!.TenMonHoc} của lớp ${selectedLop!!.TenLopHoc} đã được cập nhật.\nThông báo: $ghiChu.",
 MaLoaiTaiKhoan = 2,
