@Composable
fun CreateLichHocScreen(
 navController: NavHostController,
 lichhocViewModel: LichHocViewModel,
 namHocViewModel: NamHocViewModel,
 monHocViewModel: MonHocViewModel,
 tuanViewModel: TuanViewModel,
 giangvienViewModel: GiangVienViewModel,
 lopHocViewModel: LopHocViewModel,
 phongMayViewModel: PhongMayViewModel,
 caHocViewModel: CaHocViewModel
) {
 val context = LocalContext.current

 var showDialog by remember { mutableStateOf(false) }
 var conflictMessage by remember { mutableStateOf("") }


 // Load dữ liệu khi khởi chạy
 LaunchedEffect(Unit) {
 namHocViewModel.getAllNamHoc()
 tuanViewModel.getAllTuan()
 giangvienViewModel.getAllGiangVien()
 phongMayViewModel.getAllPhongMay()
 monHocViewModel.getAllMonHoc()
 lopHocViewModel.getAllLopHoc()
 caHocViewModel.getAllCaHoc()
 lichhocViewModel.getAllLichHoc()
 }

 // State dropdown
 var selectedGiangVien by remember { mutableStateOf<GiangVien?>(null) }
 var selectedPhong by remember { mutableStateOf<PhongMay?>(null) }
 var selectedTuanTu by remember { mutableStateOf<Tuan?>(null) }
 var selectedTuanDen by remember { mutableStateOf<Tuan?>(null) }
 var selectedMonHoc by remember { mutableStateOf<MonHoc?>(null) }
 var selectedThu by remember { mutableStateOf<String?>(null) }
 var selectedLop by remember { mutableStateOf<LopHoc?>(null) }
 var selectedCaHoc by remember { mutableStateOf<CaHoc?>(null) }
 var ghiChu by remember { mutableStateOf("") }

 // Dữ liệu nguồn
 val danhSachGiangVien = giangvienViewModel.danhSachAllGiangVien.filter { it.TrangThai == 1 }
 val danhSachPhong =
 phongMayViewModel.danhSachAllPhongMay.filter { it.TrangThai == 1 && it.LoaiPhong == 1 }
 val danhSachNamHoc = namHocViewModel.danhSachAllNamHoc.filter { it.TrangThai == 1 }
 val danhSachTuan = tuanViewModel.danhSachAllTuan
 val danhSachMonHoc = monHocViewModel.danhSachAllMonHoc.filter { it.TrangThai == 1 }
 val danhsachlophoc = lopHocViewModel.danhSachAllLopHoc.filter { it.TrangThai == 1 }
 val danhsachAllLichHoc = lichhocViewModel.danhSachLichHoc.filter { it.TrangThai == 1 }

 val danhSachThu = listOf(
 "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7", "Chủ Nhật"
 )

 val thuToOffset = mapOf(
 "Thứ 2" to 0,
 "Thứ 3" to 1,
 "Thứ 4" to 2,
 "Thứ 5" to 3,
 "Thứ 6" to 4,
 "Thứ 7" to 5,
 "Chủ Nhật" to 6
 )

 val selectedNamHoc = remember(danhSachNamHoc) {
 danhSachNamHoc.firstOrNull { it.TrangThai == 1 }
 }

 val danhSachTuanTheoNam = remember(selectedNamHoc, danhSachTuan) {
 danhSachTuan.filter { it.MaNam == selectedNamHoc?.MaNam }
 }

 // Filter ca học dựa trên phòng, thứ và các ngày cụ thể sẽ dạy
 val danhsachcahoc = remember(
 selectedPhong, selectedThu, selectedTuanTu, selectedTuanDen,
 caHocViewModel.danhSachAllCaHoc, danhsachAllLichHoc, danhSachTuan
 ) {
 val allCaHoc = caHocViewModel.danhSachAllCaHoc.filter { it.TrangThai == 1 }

 if (selectedPhong != null && selectedThu != null && selectedTuanTu != null && selectedTuanDen != null) {
 // Tính toán tất cả các ngày dạy dựa trên tuần từ - tuần đến
 val thuOffset = thuToOffset[selectedThu] ?: 0
 val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

 val tuanBatDauIndex = danhSachTuan.indexOfFirst { it.MaTuan == selectedTuanTu?.MaTuan }
 val tuanKetThucIndex =
 danhSachTuan.indexOfFirst { it.MaTuan == selectedTuanDen?.MaTuan }

 val ngayDayList = mutableListOf<String>()

 if (tuanBatDauIndex != -1 && tuanKetThucIndex != -1 && tuanBatDauIndex <= tuanKetThucIndex) {
 for (i in tuanBatDauIndex..tuanKetThucIndex) {
 val tuan = danhSachTuan[i]
 try {
 val ngayDay = LocalDate.parse(tuan.NgayBatDau, formatter)
 .plusDays(thuOffset.toLong())
 .format(formatter)
 ngayDayList.add(ngayDay)
 } catch (e: Exception) {
 // Bỏ qua ngày không hợp lệ
 }
 }
 }

 // Lọc ra những ca đã có lịch dạy trong phòng vào các ngày cụ thể này
 val usedCaHoc = danhsachAllLichHoc.filter { lichHoc ->
 lichHoc.MaPhong == selectedPhong?.MaPhong &&
 lichHoc.NgayDay in ngayDayList
 }.map { it.MaCaHoc }.toSet()

 // Chỉ hiển thị những ca chưa được sử dụng
 allCaHoc.filter { caHoc ->
 caHoc.MaCaHoc !in usedCaHoc
 }
 } else {
 allCaHoc
 }
 }

 Card(
 colors = CardDefaults.cardColors(containerColor = Color.White),
 modifier = Modifier
 .fillMaxWidth()
 .height(630.dp),
 elevation = CardDefaults.cardElevation(8.dp)
 ) {

 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(16.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.Center
 ) {

 Text(
 modifier = Modifier.padding(bottom = 16.dp),
 text = "Thêm Lịch Dạy",
 color = Color(0xFF1B8DDE),
 fontWeight = FontWeight.ExtraBold,
 fontSize = 20.sp
 )

 HorizontalDivider(
 modifier = Modifier
 .padding(bottom = 8.dp)
 .fillMaxWidth(),
 thickness = 2.dp,
 color = Color(0xFF1B8DDE),
 )

 LazyColumn(
 modifier = Modifier
 .weight(1f)
 .fillMaxWidth()
 ) {
 item {
 Text("Giảng Viên", fontWeight = FontWeight.Bold, color = Color.Black)
 CustomDropdownSelector(
 label = "Giảng viên",
 items = danhSachGiangVien,
 selectedItem = selectedGiangVien,
 itemLabel = { it.TenGiangVien },
 onItemSelected = { selectedGiangVien = it }
 )
 }

 item {
 Text("Phòng Dạy", fontWeight = FontWeight.Bold, color = Color.Black)
 CustomDropdownSelector(
 label = "Phòng",
 items = danhSachPhong,
 selectedItem = selectedPhong,
 itemLabel = { it.TenPhong },
 onItemSelected = { selectedPhong = it }
 )
 }

 item {
 Text("Lớp", fontWeight = FontWeight.Bold, color = Color.Black)
 CustomDropdownSelector(
 label = "Lớp",
 items = danhsachlophoc,
 selectedItem = selectedLop,
 itemLabel = { it.TenLopHoc },
 onItemSelected = { selectedLop = it }
 )
 }

 item {
 Text("Tuần Bắt Đầu", fontWeight = FontWeight.Bold, color = Color.Black)
 CustomDropdownSelector(
 label = "Từ tuần",
 items = danhSachTuanTheoNam.filter { it.MaNam == selectedNamHoc?.MaNam },
 selectedItem = selectedTuanTu,
 itemLabel = { it.TenTuan },
 onItemSelected = { selectedTuanTu = it }
 )
 }

 item {
 Text("Tuần Kết Thúc", fontWeight = FontWeight.Bold, color = Color.Black)
 CustomDropdownSelector(
 label = "Đến tuần",
 items = danhSachTuanTheoNam.filter { it.MaNam == selectedNamHoc?.MaNam },
 selectedItem = selectedTuanDen,
 itemLabel = { it.TenTuan },
 onItemSelected = { selectedTuanDen = it }
 )
 }

 item {
 Text("Thứ", fontWeight = FontWeight.Bold, color = Color.Black)

 CustomDropdownSelector(
 label = "Thứ",
 items = danhSachThu,
 selectedItem = selectedThu,
 itemLabel = { it },
 onItemSelected = { selectedThu = it }
 )
 }

 item {
 Text("Ca Học", fontWeight = FontWeight.Bold, color = Color.Black)

 CustomDropdownSelector(
 label = "Ca Học",
 items = danhsachcahoc,
 selectedItem = selectedCaHoc,
 itemLabel = { it.TenCa },
 onItemSelected = { selectedCaHoc = it }
 )
 }

 item {
 Text("Môn", fontWeight = FontWeight.Bold, color = Color.Black)
 CustomDropdownSelector(
 label = "Môn học",
 items = danhSachMonHoc,
 selectedItem = selectedMonHoc,
 itemLabel = { it.TenMonHoc },
 onItemSelected = { selectedMonHoc = it }
 )
 }
 }

 Button(
 onClick = {
 if (
 selectedGiangVien != null && selectedPhong != null &&
 selectedTuanTu != null && selectedTuanDen != null && selectedThu != null &&
 selectedLop != null && selectedCaHoc != null && selectedMonHoc != null
 ) {
 val thuOffset = thuToOffset[selectedThu] ?: 0
 val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

 val tuanBatDauIndex =
 danhSachTuan.indexOfFirst { it.MaTuan == selectedTuanTu?.MaTuan }
 val tuanKetThucIndex =
 danhSachTuan.indexOfFirst { it.MaTuan == selectedTuanDen?.MaTuan }

 if (tuanBatDauIndex != -1 && tuanKetThucIndex != -1 && tuanBatDauIndex <= tuanKetThucIndex) {
 val lichHocList = mutableListOf<LichHoc>()

 for (i in tuanBatDauIndex..tuanKetThucIndex) {
 val tuan = danhSachTuan[i]
 val ngayDay = try {
 LocalDate.parse(tuan.NgayBatDau, formatter)
 .plusDays(thuOffset.toLong())
 .format(formatter)
 } catch (e: Exception) {
 null
 }

 if (ngayDay != null) {
 // Lấy giờ kết thúc của ca học
 val gioKetThuc = try {
 LocalTime.parse(selectedCaHoc!!.GioKetThuc)
 } catch (e: Exception) {
 null
 }

 // Kết hợp ngày và giờ để tạo LocalDateTime
 val ngayDayDate = LocalDate.parse(ngayDay, formatter)
 val ngayDayGioKetThuc =
 gioKetThuc?.let { LocalDateTime.of(ngayDayDate, it) }

 // So sánh với giờ hiện tại
 if (ngayDayGioKetThuc != null && ngayDayGioKetThuc.isBefore(
 LocalDateTime.now()
 )
 ) {
 conflictMessage =
 "Không thể thêm lịch:\nTuần ${tuan.TenTuan}\nNgày ${
 formatNgay(
 ngayDay
 )
 }, ${selectedCaHoc?.TenCa} đã kết thúc."
 showDialog = true
 return@Button
 }

 // Kiểm tra trùng phòng
 val isTrungCaTrongPhong = danhsachAllLichHoc.any {
 it.NgayDay == ngayDay &&
 it.MaPhong == selectedPhong?.MaPhong &&
 it.MaCaHoc == selectedCaHoc?.MaCaHoc
 }

 if (isTrungCaTrongPhong) {
 conflictMessage =
 "Trùng lịch phòng:\nTuần ${tuan.TenTuan}\nNgày ${
 formatNgay(
 ngayDay
 )
 }, phòng ${selectedPhong?.TenPhong}, ${selectedCaHoc?.TenCa} đã có lịch dạy!"
 showDialog = true
 return@Button
 }
 //kiểm tra trùng ca của lớp
 val isTrungCaCuaLop = danhsachAllLichHoc.any {
 it.NgayDay == ngayDay &&
 it.MaLopHoc == selectedLop?.MaLopHoc &&
 it.MaCaHoc == selectedCaHoc?.MaCaHoc // so khớp cả ca
 }

 if (isTrungCaCuaLop) {
 conflictMessage =
 "Trùng lịch lớp:\nTuần ${tuan.TenTuan}\n" +
 "Ngày ${formatNgay(ngayDay)}, lớp ${selectedLop?.TenLopHoc} " +
 "đã có lịch ${selectedCaHoc?.TenCa}!"
 showDialog = true
 return@Button
 }

 // Kiểm tra trùng ca của giảng viên
 val isTrungCaCuaGV = danhsachAllLichHoc.any {
 it.NgayDay == ngayDay &&
 it.MaGV == selectedGiangVien?.MaGV &&
 it.MaCaHoc == selectedCaHoc?.MaCaHoc
 }

 if (isTrungCaCuaGV) {
 conflictMessage =
 "Trùng lịch giảng viên:\nTuần ${tuan.TenTuan}\nNgày ${
 formatNgay(
 ngayDay
 )
 }, giảng viên ${selectedGiangVien?.TenGiangVien} đã có lịch dạy ${selectedCaHoc?.TenCa}!"
 showDialog = true
 return@Button
 }


 val lichHoc = LichHoc(
 MaLichHoc = 0,
 MaGV = selectedGiangVien!!.MaGV,
 MaPhong = selectedPhong!!.MaPhong,
 MaLopHoc = selectedLop!!.MaLopHoc,
 MaMonHoc = selectedMonHoc!!.MaMonHoc,
 MaCaHoc = selectedCaHoc?.MaCaHoc ?: 0,
 MaTuan = tuan.MaTuan.toInt(),
 Thu = selectedThu!!,
 NgayDay = ngayDay,
 GhiChu = "",
 TrangThai = 1
 )
 lichHocList.add(lichHoc)
 }

 }

 lichhocViewModel.createListLichHoc(lichHocList)

 Toast.makeText(
 context,
 "Đã tạo ${lichHocList.size} lịch học",
 Toast.LENGTH_SHORT
 ).show()
 navController.navigate(NavRoute.QUANLYLICHHOC.route + "?startIndex=0")
 } else {
 Toast.makeText(
 context,
 "Tuần bắt đầu/kết thúc không hợp lệ",
 Toast.LENGTH_SHORT
 ).show()
 }
 } else {
 Toast.makeText(
 context,
 "Vui lòng chọn đầy đủ thông tin",
 Toast.LENGTH_SHORT
 ).show()
 }
 },
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(12.dp),
 colors = ButtonDefaults.buttonColors(Color(0XFF1B8DDE))
 ) {
 Text("Thêm Lịch Dạy", color = Color.White, fontWeight = FontWeight.Bold)
 }

 if (showDialog) {
 AlertDialog(
 onDismissRequest = { showDialog = false },
 title = {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 modifier = Modifier.padding(bottom = 8.dp)
 ) {
 Icon(
 imageVector = Icons.Default.Warning,
 contentDescription = null,
 tint = Color(0xFFD32F2F),
 modifier = Modifier.size(28.dp)
 )
 Spacer(modifier = Modifier.width(8.dp))
 Text(
 text = "Trùng lịch dạy",
 style = MaterialTheme.typography.titleLarge.copy(
 fontWeight = FontWeight.Bold,
 color = Color(0xFFD32F2F)
 )
 )
 }
 },
 text = {
 Text(
 text = conflictMessage,
 fontWeight = FontWeight.Bold,
 )
 },
 confirmButton = {
 TextButton(
 onClick = { showDialog = false },
 modifier = Modifier
 .padding(8.dp)
 .background(Color(0xFFD32F2F), shape = RoundedCornerShape(8.dp))
 ) {
 Text(
 "Đóng",
 color = Color.White,
 modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
 )
 }
 },
 shape = RoundedCornerShape(16.dp),
 containerColor = Color.White,
 tonalElevation = 8.dp
 )
 }

 }
 }
}

@OptIn(ExperimentalMaterialApi::class)
@Composable
fun <T> CustomDropdownSelector(
 label: String,
 items: List<T>,
 selectedItem: T?,
 itemLabel: (T) -> String,
 onItemSelected: (T) -> Unit,
 modifier: Modifier = Modifier,
 enabled: Boolean = true
) {
 var expanded by remember { mutableStateOf(false) }

 ExposedDropdownMenuBox(
 expanded = expanded,
 onExpandedChange = { if (enabled) expanded = !expanded },
 modifier = modifier
 ) {
 OutlinedTextField(
 value = selectedItem?.let { itemLabel(it) } ?: "",
 onValueChange = {},
 readOnly = true,
 enabled = enabled,
 trailingIcon = {
 if (enabled) {
 ExposedDropdownMenuDefaults.TrailingIcon(expanded = expanded)
 }
 },
 modifier = Modifier
 .padding(bottom = 16.dp)
 .fillMaxWidth(),
 placeholder = { Text(label) },
 shape = RoundedCornerShape(12.dp),
 colors = OutlinedTextFieldDefaults.colors(
 unfocusedContainerColor = Color.White,
 focusedContainerColor = Color.White,
 disabledContainerColor = Color.White,
 focusedBorderColor = Color.Black,
 unfocusedBorderColor = Color.Black,
 disabledBorderColor = Color.Black,
 focusedTextColor = Color.Black,
 unfocusedTextColor = Color.Black,
 disabledTextColor = Color.Black
 )
 )


 if (enabled) {
 ExposedDropdownMenu(
 expanded = expanded,
 onDismissRequest = { expanded = false }
 ) {
 items.forEach { item ->
 DropdownMenuItem(
 text = { Text(itemLabel(item)) },
 onClick = {
 onItemSelected(item)
 expanded = false
 }
 )
 }
 }
 }
 }
}






